catalog_script_client.script:
var csrAttributes = ['subject_common_name', 'subject_alternative_name', 'organization', 'organizational_unit', 'locality', 'province', 'country', 'email', 'csr'];

function onChange(control, oldValue, newValue, isLoading) {
    if (!newValue)
        return;

    clearCatalogFormFieldsValue();

    var certMgmtUtil = new GlideAjax('sn_disco_certmgmt.DiscoveryCertificateManagement');
    certMgmtUtil.addParam('sysparm_name', 'getCertificateDetailsByCertId');
    certMgmtUtil.addParam('sysparm_id', newValue);
    certMgmtUtil.getXML(setAutopopulateField);

    function setAutopopulateField(response) {
        var rootIssuer = response.responseXML.documentElement.getAttribute("answer");
        if (rootIssuer) {
            var certObj = JSON.parse(rootIssuer);
            g_form.setValue('certificate_expires_on', (certObj.cert_expiry_date_user_timezone) ? certObj.cert_expiry_date_user_timezone : '');
            g_form.setValue('subject_common_name', certObj.subject_common_name);
            g_form.setValue('subject_alternative_name', certObj.subject_alternative_name_display);
            g_form.setValue('organization', certObj.subject_organization);
            g_form.setValue('organizational_unit', certObj.subject_organizational_unit);
            g_form.setValue('locality', certObj.subject_locality);
            g_form.setValue('province', certObj.subject_state);
            g_form.setValue('country', certObj.subject_country);
            g_form.setValue('email', certObj.subject_email);
            g_form.setValue('renewal_tracking', certObj.renewal_tracking);
			g_form.setValue('environment', certObj.environment);
        } else {
            clearCatalogFormFieldsValue();
        }
    }

    function clearCatalogFormFieldsValue() {
        csrAttributes.forEach(function(field) {
            g_form.setValue(field, '');
        });
    }

}
